namespace SmartMix.Core.Domain.Entities.Licenses;
public class LicenseInfo { public int LicenseType { get; set; } public DateTime EndDate { get; set; } public string SerialNumber { get; set; } = string.Empty; public string HardwareId { get; set; } = string.Empty; public bool IsActive { get; set; } public DateTime ActivatedAt { get; set; } public int MaxLines { get; set; } = 1; public int MaxMixers { get; set; } = 1; public bool IsPermanent => LicenseType == 1; public bool IsExpired => !IsPermanent && EndDate < DateTime.UtcNow; public TimeSpan TimeRemaining => IsPermanent ? TimeSpan.MaxValue : EndDate - DateTime.UtcNow; }
